    static int[] head, to, nextEdge;
    static int edgeCount = 0;

    static void addEdge(int u, int v) {
        to[edgeCount] = v;
        nextEdge[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    static int[] bfsOrder;
    static int[] parent;
    static int[] max_u;
    static int[] min_c;

    static final int INF = 1_000_000_000;
    static final int NEG_INF = -1_000_000_000;

    static boolean check(int R, int K) {
        Arrays.fill(max_u, NEG_INF);
        Arrays.fill(min_c, INF);
        int centers = 0;

        for (int i = n - 1; i >= 0; i--) {
            int u = bfsOrder[i];
            max_u[u] = Math.max(max_u[u], 0);

            if (min_c[u] + max_u[u] <= R) {
                max_u[u] = NEG_INF;
            } else if (max_u[u] == R) {
                centers++;
                min_c[u] = 0;
                max_u[u] = NEG_INF;
            }

            if (u != 1) {
                int p = parent[u];
                if (max_u[u] != NEG_INF) {
                    max_u[p] = Math.max(max_u[p], max_u[u] + 1);
                }
                if (min_c[u] != INF) {
                    min_c[p] = Math.min(min_c[p], min_c[u] + 1);
                }
            } else {
                if (max_u[u] >= 0) {
                    centers++;
                }
            }
        }

        return centers <= K;
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        n = sc.nextInt();
        if (n == -1) return;
        k = sc.nextInt();

        head = new int[n + 1];
        Arrays.fill(head, -1);
        to = new int[2 * (n - 1)];
        nextEdge = new int[2 * (n - 1)];

        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            addEdge(u, v);
            addEdge(v, u);
        }

        bfsOrder = new int[n];
        parent = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        int headIdx = 0, tailIdx = 0;
        bfsOrder[tailIdx++] = 1;
        visited[1] = true;
        parent[1] = 0;

        while (headIdx < tailIdx) {
            int u = bfsOrder[headIdx++];
            for (int e = head[u]; e != -1; e = nextEdge[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    bfsOrder[tailIdx++] = v;
                }
            }
        }

        max_u = new int[n + 1];
        min_c = new int[n + 1];

        int low = 1, high = n - 1;
        int ans = high;

        while (low <= high) {
            int mid = (low + high) / 2;
            if (check(mid, k)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }
}
