const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;
    const k = readInt();

    const head = new Int32Array(n + 1).fill(-1);
    const to = new Int32Array(2 * n);
    const next = new Int32Array(2 * n);
    let edgeCount = 0;

    function addEdge(u, v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    for (let i = 0; i < n - 1; i++) {
        const u = readInt();
        const v = readInt();
        addEdge(u, v);
        addEdge(v, u);
    }

    // BFS para definir a ordem topológica (pais e filhos)
    const parent = new Int32Array(n + 1);
    const order = new Int32Array(n);
    let headQueue = 0;
    let tailQueue = 0;

    order[tailQueue++] = 1;
    parent[1] = 0;

    while (headQueue < tailQueue) {
        const u = order[headQueue++];
        for (let e = head[u]; e !== -1; e = next[e]) {
            const v = to[e];
            if (v !== parent[u]) {
                parent[v] = u;
                order[tailQueue++] = v;
            }
        }
    }

    const max_uncovered = new Int32Array(n + 1);
    const min_covered = new Int32Array(n + 1);
    const INF = 1e9;

    function check(R) {
        let centers = 0;
        for (let i = 1; i <= n; i++) {
            max_uncovered[i] = 0;
            min_covered[i] = INF;
        }

        // Processar em pós-ordem (do último na BFS até o primeiro)
        for (let i = n - 1; i >= 0; i--) {
            const u = order[i];

            if (max_uncovered[u] + min_covered[u] <= R) {
                max_uncovered[u] = -INF;
            }

            if (max_uncovered[u] === R) {
                centers++;
                min_covered[u] = 0;
                max_uncovered[u] = -INF;
            }

            const p = parent[u];
            if (p !== 0) {
                if (max_uncovered[u] >= 0) {
                    if (max_uncovered[u] + 1 > max_uncovered[p]) {
                        max_uncovered[p] = max_uncovered[u] + 1;
                    }
                }
                if (min_covered[u] < INF) {
                    if (min_covered[u] + 1 < min_covered[p]) {
                        min_covered[p] = min_covered[u] + 1;
                    }
                }
            }
        }

        if (max_uncovered[1] >= 0) {
            centers++;
        }

        return centers <= k;
    }

    let low = 0;
    let high = n;
    let ans = n;

    while (low <= high) {
        const mid = (low + high) >> 1;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    console.log(ans);
}

